* { box-sizing: border-box; }

:root {
  color-scheme: dark;
  font-family: system-ui, sans-serif;
  font-size: 16px;
  background: #17231e;
  color: #f5f0df;
}

body {
  min-width: 320px;
  min-height: 100vh;
  margin: 0;
  display: grid;
  place-items: center;
  padding: 24px;
  background-color: #17231e;
  background-image: linear-gradient(45deg, #20332a 25%, transparent 25%), linear-gradient(-45deg, #20332a 25%, transparent 25%), linear-gradient(45deg, transparent 75%, #20332a 75%), linear-gradient(-45deg, transparent 75%, #20332a 75%);
  background-size: 48px 48px;
  background-position: 0 0, 0 24px, 24px -24px, -24px 0;
}

.clock-card {
  width: min(100%, 620px);
  padding: clamp(24px, 6vw, 44px);
  border: 3px solid #c5a66a;
  border-radius: 10px;
  background: #263a30;
  box-shadow: 8px 8px 0 #101914;
  text-align: center;
}

.card-header { margin-bottom: 28px; }
.eyebrow { margin: 0 0 8px; color: #c5a66a; font-size: 0.85rem; font-weight: 800; letter-spacing: 0.15em; }
h1 { margin: 0; font-size: clamp(1.7rem, 6vw, 2.4rem); line-height: 1.15; }
.hint { margin: 10px 0 0; color: #cbd5c6; }

.clocks { display: grid; grid-template-columns: 1fr 1fr; gap: 14px; }
.player-clock {
  min-width: 0;
  min-height: 190px;
  padding: 18px 10px;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 10px;
  border: 3px solid #e6dfcc;
  border-radius: 8px;
  background: #f0ead8;
  color: #17231e;
  cursor: pointer;
  font: inherit;
  transition: transform 120ms ease, box-shadow 120ms ease, background-color 120ms ease;
}
.player-clock:hover { transform: translateY(-2px); box-shadow: 0 5px 0 #c5a66a; }
.player-clock:active { transform: translateY(2px); box-shadow: none; }
.player-clock:focus-visible, .pause-button:focus-visible { outline: 3px solid #f4ce76; outline-offset: 4px; }
.player-clock.active { border-color: #f4ce76; box-shadow: 0 0 0 3px #c5a66a; }
.player-clock[disabled] { cursor: default; opacity: 0.78; }
.player-clock[disabled]:hover { transform: none; box-shadow: none; }
.dark-clock { background: #1c2923; color: #f5f0df; border-color: #52665b; }
.dark-clock.active { border-color: #f4ce76; }
.player-name { display: flex; align-items: center; gap: 8px; font-size: 1.1rem; font-weight: 750; }
.piece { font-size: 1.5rem; line-height: 1; }
.white-piece { color: #fff; text-shadow: 1px 1px #17231e, -1px -1px #17231e; }
.black-piece { color: #c5a66a; }
.time { font-variant-numeric: tabular-nums; font-size: clamp(2.2rem, 10vw, 3.5rem); font-weight: 800; letter-spacing: 0.02em; line-height: 1.05; }
.turn-label { min-height: 1.3em; color: #617268; font-size: 0.8rem; font-weight: 800; letter-spacing: 0.12em; }
.dark-clock .turn-label { color: #b6c2b7; }
.active .turn-label { color: #8a6727; }
.dark-clock.active .turn-label { color: #f4ce76; }
.status { min-height: 1.5em; margin: 22px 0 16px; color: #e5ddc8; font-weight: 650; }
.pause-button {
  min-width: 150px;
  padding: 12px 24px;
  border: 2px solid #c5a66a;
  border-radius: 5px;
  background: #c5a66a;
  color: #17231e;
  cursor: pointer;
  font: inherit;
  font-weight: 800;
  transition: background-color 120ms ease, transform 120ms ease;
}
.pause-button:hover:not(:disabled) { background: #f4ce76; }
.pause-button:active:not(:disabled) { transform: translateY(2px); }
.pause-button:disabled { cursor: default; opacity: 0.55; }

@media (max-width: 420px) {
  body { padding: 16px; }
  .clock-card { padding: 24px 16px; }
  .clocks { gap: 10px; }
  .player-clock { min-height: 170px; padding: 14px 6px; }
}

const START_SECONDS = 5 * 60;
const players = {
  white: { button: document.getElementById('white-clock'), time: document.getElementById('white-time'), turn: document.getElementById('white-turn'), seconds: START_SECONDS },
  black: { button: document.getElementById('black-clock'), time: document.getElementById('black-time'), turn: document.getElementById('black-turn'), seconds: START_SECONDS }
};
const status = document.getElementById('status');
const pauseButton = document.getElementById('pause-button');
let active = null;
let paused = false;
let flagged = false;
let lastTick = 0;
let timerId = null;

function formatTime(seconds) {
  return `${Math.floor(seconds / 60)}:${String(seconds % 60).padStart(2, '0')}`;
}

function render() {
  for (const [name, player] of Object.entries(players)) {
    player.time.textContent = formatTime(player.seconds);
    const isActive = active === name && !paused && !flagged;
    player.button.classList.toggle('active', isActive);
    player.button.setAttribute('aria-pressed', String(active === name && !paused && !flagged));
    player.button.setAttribute('aria-label', `${name === 'white' ? 'White' : 'Black'} clock, ${formatTime(player.seconds)} remaining${isActive ? ', running' : ''}. Tap to start or switch turns.`);
    player.turn.textContent = flagged && active === name ? 'FLAG!' : isActive ? 'YOUR TURN' : paused && active === name ? 'PAUSED' : active === name && !flagged ? 'PAUSED' : 'READY';
  }
  pauseButton.textContent = paused ? 'Resume' : 'Pause';
  pauseButton.setAttribute('aria-label', paused ? 'Resume the clocks' : 'Pause both clocks');
  pauseButton.disabled = active === null || flagged;
}

function stopTimer() {
  if (timerId !== null) cancelAnimationFrame(timerId);
  timerId = null;
}

function tick(now) {
  if (!active || paused || flagged) return;
  const elapsed = Math.floor((now - lastTick) / 1000);
  if (elapsed > 0) {
    players[active].seconds = Math.max(0, players[active].seconds - elapsed);
    lastTick += elapsed * 1000;
    if (players[active].seconds === 0) {
      flagged = true;
      status.textContent = `${active === 'white' ? 'White' : 'Black'} flagged!`;
      stopTimer();
      render();
      return;
    }
    render();
  }
  timerId = requestAnimationFrame(tick);
}

function startTurn(name) {
  if (flagged) return;
  if (active === name && !paused) return;
  active = name;
  paused = false;
  lastTick = performance.now();
  status.textContent = `${name === 'white' ? 'White' : 'Black'} to move.`;
  stopTimer();
  timerId = requestAnimationFrame(tick);
  render();
}

for (const [name, player] of Object.entries(players)) {
  player.button.addEventListener('click', () => startTurn(name));
}

pauseButton.addEventListener('click', () => {
  if (active === null || flagged) return;
  if (paused) {
    paused = false;
    lastTick = performance.now();
    status.textContent = `${active === 'white' ? 'White' : 'Black'} to move.`;
    timerId = requestAnimationFrame(tick);
  } else {
    paused = true;
    stopTimer();
    status.textContent = 'Clock paused.';
  }
  render();
});

render();
